<template>
  <ADrawer :open="appStore.themeDrawerVisible" :title="$t('theme.themeDrawerTitle')" :closable="false" :body-style="{ padding: '0px' }" @close="appStore.closeThemeDrawer">
    <template #extra><ButtonIcon icon="ant-design:close-outlined" class="h-[28px]" @click="appStore.closeThemeDrawer" /></template>
    <SimpleScrollbar><div class="px-[24px] pb-[24px] pt-[8px]"><SchemaSection /><ModeSection /><ColorSection /><PageSection /></div></SimpleScrollbar>
    <template #footer><div class="flex justify-between"><AButton danger @click="resetConfig">{{ $t('theme.configOperation.resetConfig') }}</AButton><div ref="domRef"><AButton type="primary">{{ $t('theme.configOperation.copyConfig') }}</AButton></div></div></template>
  </ADrawer>
</template>

<script setup lang="tsx">
import { computed, defineComponent, onMounted, ref, Transition, TransitionGroup } from 'vue';
import type { SegmentedOption } from 'ant-design-vue/es/segmented/src/segmented';
import type { TooltipPlacement } from 'ant-design-vue/es/tooltip';
import Clipboard from 'clipboard';
import { resetCacheStrategyOptions, themeLayoutModeRecord, themePageAnimationModeOptions, themeSchemaRecord, themeScrollModeOptions, themeTabModeOptions } from '@/constants/app';
import { useAppStore } from '@/store/system/app';
import { useThemeStore } from '@/store/system/theme';
import { $t } from '@/locales';
import SimpleScrollbar from '@/components/system/simple-scrollbar.vue';
import ColorPicker from '@/components/system/color-picker.vue';

defineOptions({ name: 'ThemeDrawer' });
const appStore = useAppStore();
const themeStore = useThemeStore();
const domRef = ref<HTMLElement | null>(null);
const layoutModes: UnionKey.ThemeLayoutMode[] = ['vertical', 'vertical-mix', 'horizontal', 'horizontal-mix'];
const schemaIcons: Record<UnionKey.ThemeScheme, string> = { light: 'material-symbols:sunny', dark: 'material-symbols:nightlight-rounded', auto: 'material-symbols:hdr-auto' };
const schemaOptions = computed<SegmentedOption[]>(() => Object.keys(themeSchemaRecord).map(item => ({ value: item, payload: { icon: schemaIcons[item as UnionKey.ThemeScheme] } })));
const showSiderInverted = computed(() => !themeStore.darkMode && themeStore.layout.mode.includes('vertical'));
const layoutMode = computed(() => themeStore.layout.mode);
const isMixLayoutMode = computed(() => layoutMode.value.includes('mix'));
const isWrapperScrollMode = computed(() => themeStore.layout.scrollMode === 'wrapper');
const pageAnimationVisible = computed(() => themeStore.page.animate);
const footerVisible = computed(() => themeStore.footer.visible);
const tabVisible = computed(() => themeStore.tab.visible);
const breadcrumbVisible = computed(() => themeStore.header.breadcrumb.visible);
const watermarkVisible = computed(() => themeStore.watermark.visible);
const hoverMode = ref<UnionKey.ThemeLayoutMode | ''>('');
const layoutCards: Record<UnionKey.ThemeLayoutMode, TooltipPlacement> = { vertical: 'bottom', 'vertical-mix': 'bottom', horizontal: 'bottom', 'horizontal-mix': 'bottom' };

const Row = defineComponent({ name: 'ThemeDrawerRow', props: { label: { type: String, required: true } }, setup(props, { slots, attrs }) { return () => <div class={['w-full flex items-center justify-between', attrs.class]}><div><span class="pr-[8px] text-base-text">{props.label}</span>{slots.suffix?.()}</div>{slots.default?.()}</div>; } });

const SchemaSection = defineComponent({ setup() { return () => <><ADivider>{$t('theme.themeSchema.title')}</ADivider><div class="flex flex-col gap-[16px]"><div class="inline-flex items-center justify-center"><ASegmented value={themeStore.themeScheme} options={schemaOptions.value} class="bg-layout" onChange={v => themeStore.setThemeScheme(v as UnionKey.ThemeScheme)} v-slots={{ label: ({ payload }: any) => <div class="w-[70px] flex justify-center"><SvgIcon icon={payload.icon} class="h-[28px] text-icon-small" /></div> }} /></div><Transition name="sider-inverted">{showSiderInverted.value ? <Row label={$t('theme.sider.inverted')}><ASwitch v-model:checked={themeStore.sider.inverted} /></Row> : null}</Transition><Row label={$t('theme.grayscale')}><ASwitch checked={themeStore.grayscale} onUpdate:checked={v => themeStore.setGrayscale(v as boolean)} /></Row><Row label={$t('theme.colourWeakness')}><ASwitch checked={themeStore.colourWeakness} onUpdate:checked={v => themeStore.setColourWeakness(v as boolean)} /></Row></div></>; } });

const ModeSection = defineComponent({ setup() { const styleOf = (key: UnionKey.ThemeLayoutMode) => ({ borderWidth: '2px', borderStyle: 'solid', borderColor: themeStore.layout.mode === key || hoverMode.value === key ? themeStore.themeColor || '#1677ff' : 'transparent' }); return () => <><ADivider>{$t('theme.layoutMode.title')}</ADivider><div class="flex flex-wrap items-center justify-center gap-x-[32px] gap-y-[16px]">{layoutModes.map(mode => <ATooltip placement={layoutCards[mode]} title={$t(themeLayoutModeRecord[mode])}><div class="flex cursor-pointer rounded-[6px]" onClick={() => !appStore.isMobile && themeStore.setThemeLayout(mode)}><div class={['h-[64px] w-[96px] gap-[6px] rounded-[4px] p-[6px] shadow transition-colors duration-300 dark:shadow-coolGray-5', mode.includes('vertical') ? 'flex' : 'flex flex-col']} style={styleOf(mode)} onMouseenter={() => (hoverMode.value = mode)} onMouseleave={() => (hoverMode.value = '')}>{mode === 'vertical' ? <><div class="h-full w-[18px] rounded-[4px] bg-[var(--color-primary-300)]"></div><div class="flex flex-1 flex-col gap-[6px]"><div class="h-[16px] rounded-[4px] bg-[var(--color-primary)]"></div><div class="flex-1 rounded-[4px] bg-[var(--color-primary-200)]"></div></div></> : mode === 'vertical-mix' ? <><div class="h-full w-[8px] rounded-[4px] bg-[var(--color-primary-300)]"></div><div class="h-full w-[16px] rounded-[4px] bg-[var(--color-primary-300)]"></div><div class="flex flex-1 flex-col gap-[6px]"><div class="h-[16px] rounded-[4px] bg-[var(--color-primary)]"></div><div class="flex-1 rounded-[4px] bg-[var(--color-primary-200)]"></div></div></> : mode === 'horizontal' ? <><div class="h-[16px] rounded-[4px] bg-[var(--color-primary)]"></div><div class="flex flex-1 gap-[6px]"><div class="flex-1 rounded-[4px] bg-[var(--color-primary-200)]"></div></div></> : <><div class="h-[16px] rounded-[4px] bg-[var(--color-primary)]"></div><div class="flex flex-1 gap-[6px]"><div class="w-[18px] rounded-[4px] bg-[var(--color-primary-300)]"></div><div class="flex-1 rounded-[4px] bg-[var(--color-primary-200)]"></div></div></>}</div></div></ATooltip>)}</div>{themeStore.layout.mode === 'horizontal-mix' ? <Row label={$t('theme.layoutMode.reverseHorizontalMix')} class="mt-[16px]"><ASwitch checked={themeStore.layout.reverseHorizontalMix} onUpdate:checked={v => themeStore.setLayoutReverseHorizontalMix(v as boolean)} /></Row> : null}</>; } });

const ColorSection = defineComponent({ setup() { return () => <><ADivider>{$t('theme.themeColor.title')}</ADivider><div class="flex flex-col gap-[12px]"><ATooltip placement="topLeft" v-slots={{ title: () => <p><span class="pr-[12px]">{$t('theme.recommendColorDesc')}</span><br /><AButton type="link" href="https://uicolors.app/create" target="_blank" class="text-gray">https://uicolors.app/create</AButton></p> }}><Row label={$t('theme.recommendColor')}><ASwitch v-model:checked={themeStore.recommendColor} /></Row></ATooltip>{Object.keys(themeStore.themeColors).map(key => <Row label={$t(`theme.themeColor.${key}` as any)}>{<><template v-slot:suffix>{key === 'info' ? <ACheckbox v-model:checked={themeStore.isInfoFollowPrimary}>{$t('theme.themeColor.followPrimary')}</ACheckbox> : null}</template><ColorPicker color={themeStore.themeColors[key as App.Theme.ThemeColorKey]} disabled={key === 'info' && themeStore.isInfoFollowPrimary} onUpdate:color={c => themeStore.updateThemeColors(key as App.Theme.ThemeColorKey, c)} /></>}</Row>)}</div></>; } });

const PageSection = defineComponent({ setup() { return () => <><ADivider>{$t('theme.pageFunTitle')}</ADivider><TransitionGroup tag="div" name="setting-list"><Row key="0" label={$t('theme.resetCacheStrategy.title')}><ASelect v-model:value={themeStore.resetCacheStrategy}>{resetCacheStrategyOptions.map(o => <ASelectOption value={o.value}>{$t(o.label)}</ASelectOption>)}</ASelect></Row><Row key="1" label={$t('theme.scrollMode.title')}><ASelect v-model:value={themeStore.layout.scrollMode} class="w-[120px]">{themeScrollModeOptions.map(o => <ASelectOption value={o.value}>{$t(o.label)}</ASelectOption>)}</ASelect></Row><Row key="1-1" label={$t('theme.page.animate')}><ASwitch v-model:checked={themeStore.page.animate} /></Row>{pageAnimationVisible.value ? <Row key="1-2" label={$t('theme.page.mode.title')}><ASelect v-model:value={themeStore.page.animateMode} class="w-[120px]">{themePageAnimationModeOptions.map(o => <ASelectOption value={o.value}>{$t(o.label)}</ASelectOption>)}</ASelect></Row> : null}{isWrapperScrollMode.value ? <Row key="2" label={$t('theme.fixedHeaderAndTab')}><ASwitch v-model:checked={themeStore.fixedHeaderAndTab} /></Row> : null}<Row key="3" label={$t('theme.header.height')}><AInputNumber v-model:value={themeStore.header.height} class="w-[120px]" /></Row><Row key="4" label={$t('theme.header.breadcrumb.visible')}><ASwitch v-model:checked={themeStore.header.breadcrumb.visible} /></Row>{breadcrumbVisible.value ? <Row key="4-1" label={$t('theme.header.breadcrumb.showIcon')}><ASwitch v-model:checked={themeStore.header.breadcrumb.showIcon} /></Row> : null}<Row key="5" label={$t('theme.tab.visible')}><ASwitch v-model:checked={themeStore.tab.visible} /></Row>{tabVisible.value ? <><Row key="5-1" label={$t('theme.tab.cache')}><ASwitch v-model:checked={themeStore.tab.cache} /></Row><Row key="5-2" label={$t('theme.tab.height')}><AInputNumber v-model:value={themeStore.tab.height} class="w-[120px]" /></Row><Row key="5-3" label={$t('theme.tab.mode.title')}><ASelect v-model:value={themeStore.tab.mode} class="w-[120px]">{themeTabModeOptions.map(o => <ASelectOption value={o.value}>{$t(o.label)}</ASelectOption>)}</ASelect></Row></> : null}{layoutMode.value === 'vertical' ? <><Row key="6-1" label={$t('theme.sider.width')}><AInputNumber v-model:value={themeStore.sider.width} class="w-[120px]" /></Row><Row key="6-2" label={$t('theme.sider.collapsedWidth')}><AInputNumber v-model:value={themeStore.sider.collapsedWidth} class="w-[120px]" /></Row></> : null}{isMixLayoutMode.value ? <><Row key="6-3" label={$t('theme.sider.mixWidth')}><AInputNumber v-model:value={themeStore.sider.mixWidth} class="w-[120px]" /></Row><Row key="6-4" label={$t('theme.sider.mixCollapsedWidth')}><AInputNumber v-model:value={themeStore.sider.mixCollapsedWidth} class="w-[120px]" /></Row></> : null}{layoutMode.value === 'vertical-mix' ? <Row key="6-5" label={$t('theme.sider.mixChildMenuWidth')}><AInputNumber v-model:value={themeStore.sider.mixChildMenuWidth} class="w-[120px]" /></Row> : null}<Row key="7" label={$t('theme.footer.visible')}><ASwitch v-model:checked={themeStore.footer.visible} /></Row>{footerVisible.value && isWrapperScrollMode.value ? <Row key="7-1" label={$t('theme.footer.fixed')}><ASwitch v-model:checked={themeStore.footer.fixed} /></Row> : null}{footerVisible.value ? <Row key="7-2" label={$t('theme.footer.height')}><AInputNumber v-model:value={themeStore.footer.height} class="w-[120px]" /></Row> : null}{footerVisible.value && layoutMode.value === 'horizontal-mix' ? <Row key="7-3" label={$t('theme.footer.right')}><ASwitch v-model:checked={themeStore.footer.right} /></Row> : null}<Row key="8" label={$t('theme.watermark.visible')}><ASwitch v-model:checked={themeStore.watermark.visible} /></Row>{watermarkVisible.value ? <Row key="8-1" label={$t('theme.watermark.text')}><AInput v-model:value={themeStore.watermark.text} placeholder="MintAdmin" class="w-[120px]" /></Row> : null}</TransitionGroup></>; } });

function resetConfig() { themeStore.resetStore(); setTimeout(() => window.$message?.success($t('theme.configOperation.resetSuccessMsg')), 50); }
onMounted(() => { if (!domRef.value) return; const c = new Clipboard(domRef.value, { text: () => themeStore.settingsJson.replace(/"\w+":/g, m => m.replace(/"/g, '')) }); c.on('success', () => window.$message?.success($t('theme.configOperation.copySuccessMsg'))); });
</script>

<style scoped lang="scss">
.sider-inverted-enter-active,.sider-inverted-leave-active{height:22px;transition:all .3s}.sider-inverted-enter-from,.sider-inverted-leave-to{transform:translateX(20px);opacity:0;height:0}.layout-header{height:16px;background-color:var(--color-primary);border-radius:4px}.layout-sider{background-color:var(--color-primary-300);border-radius:4px}.layout-main{flex:1 1 0%;background-color:var(--color-primary-200);border-radius:4px}.vertical-wrapper{flex:1 1 0%;display:flex;flex-direction:column;gap:6px}.horizontal-wrapper{flex:1 1 0%;display:flex;gap:6px}.setting-list-move,.setting-list-enter-active,.setting-list-leave-active{transition:all .3s}.setting-list-enter-from,.setting-list-leave-to{opacity:0;transform:translateX(-30px)}.setting-list-leave-active{position:absolute}
</style>
